import { useCallback, useEffect, useRef, useState } from "react";
import { View } from "react-native";
import { useTheme } from "react-native-paper";
import { isDemo } from "../../backend/Demo";
import { serializeSaveData } from "../../backend/SaveData";
import { electron, isElectron } from "../../utils/ElectronUtils";
import { t } from "../../utils/I18n";
import { Button } from "./Button";
import { loadFromSerializedData } from "./LoadGameContainer";
import Styles from "./Styles";
import { Text } from "./Text";
import { useGameState } from "./useGameState";

let backupDone = false;

export function SaveDataBackupper() {
  if (!isElectron()) {
    return null;
  }

  const state = useGameState();

  const stateRef = useRef(state);
  stateRef.current = state;

  const backupCallback = useCallback(async () => {
    electron().ipcRenderer.send(
      "saveFileBackup",
      await serializeSaveData(stateRef.current),
    );
    backupDone = true;
  }, []);

  useEffect(() => {
    const interval = setInterval(async () => {
      try {
        await backupCallback();
      } catch (e: any) {
        throw e;
      }
    }, 15 * 60 * 1000); // 15 min
    return () => {
      clearTimeout(interval);
    };
  }, [backupCallback]);

  // When rendering the first time, back up the save
  useEffect(() => {
    if (!backupDone) {
      backupCallback();
    }
  }, [backupCallback]);

  // Do not render anything
  return null;
}

export function BackupsWarning() {
  if (!isElectron()) {
    return null;
  }

  const state = useGameState();
  const stateRef = useRef(state);
  stateRef.current = state;

  const isFirstTime =
    (state.world.totalTimesResetted ?? 0) === 0 &&
    (state.global.newGamePlusCount ?? 0) === 0;

  const [backupContents, setBackupContents] = useState("");
  const backupsGetter = useCallback(async () => {
    const value = await electron().ipcRenderer.invoke(
      "getLatestBackupContents",
    );
    console.warn("got backup contents", value);
    setBackupContents(value);
  }, []);
  useEffect(() => {
    backupsGetter();
  }, []);

  const showWarning =
    isFirstTime && !isDemo() && backupContents != "" && backupContents != null;

  const [loadMessage, setLoadMessage] = useState("");

  const theme = useTheme();

  const loadBackupContents = useCallback(() => {
    loadFromSerializedData(backupContents, setLoadMessage, stateRef);
  }, [backupContents]);

  if (!showWarning) {
    return null;
  }

  return (
    <View>
      <Text style={{ color: theme.colors.error }}>
        {t(
          "It appears that your save data was lost or deleted for some reason. However, a backup save file has been found. You may be able to recover most of your progress by loading this backup. You can do so below.",
        )}
      </Text>
      <Button style={Styles.mt8} onPress={loadBackupContents}>
        {t("Load latest backup")}
      </Button>
      {loadMessage != "" && (
        <Text style={[Styles.mt8, { color: theme.colors.error }]}>
          {loadMessage}
        </Text>
      )}
    </View>
  );
}
