import color from "color";
import { useCallback, useMemo, useRef } from "react";
import { StyleSheet, View } from "react-native";
import { useTheme } from "react-native-paper";
import { getThemeByElementAndDarkMode } from "../../Themes";
import { SpellAutocastCategory } from "../../backend/autocast/Autocast";
import { Spell } from "../../backend/spells/Spell";
import { Spells } from "../../backend/spells/Spells";
import ChannelFour from "../../backend/spells/channeling/ChannelFour";
import { t } from "../../utils/I18n";
import { Button } from "../utility/Button";
import Styles from "../utility/Styles";
import { GameIcon } from "../utility/icons/GameIcon";
import { useGameState } from "../utility/useGameState";

function QuickChannelButton(props: { spell: Spell }) {
  const spell = props.spell;
  const element = spell.getElement();
  const state = useGameState();
  const stateRef = useRef(state);
  stateRef.current = state;
  const disabled = !spell.isEnabled(state);
  const buttonContents =
    element != null ? (
      <View style={disabled && { opacity: 0.5 }}>
        <GameIcon icon={element.toLowerCase()} />
      </View>
    ) : spell == ChannelFour ? (
      t("Four")
    ) : (
      t("All")
    );

  const buttonOnPress = useCallback(() => {
    stateRef.current.apply((state) =>
      spell.doAction({ isAutomatic: false }, state),
    );
  }, [spell]);

  const theme = useTheme();
  const elementTheme =
    element != null ? getThemeByElementAndDarkMode(element, theme.dark) : theme;

  return useMemo(
    () => (
      <Button
        compact={true}
        enableAutoRepress={true}
        onPress={buttonOnPress}
        style={styles.buttonStyle}
        passthroughStyle={
          element != null &&
          !disabled && {
            backgroundColor: color(
              elementTheme.colors.primaryContainer,
            ).toString(),
          }
        }
        labelStyle={styles.buttonLabelStyle}
        contentStyle={styles.buttonContentStyle}
        theme={elementTheme}
        // @ts-ignore I added this myself
        TextComponent={element != null ? View : undefined}
        disabled={disabled}
        disableDisabledRenderingOptimization={true}
        accessibilityLabel={spell.getSpellName()}
      >
        {buttonContents}
      </Button>
    ),
    [buttonOnPress, element, disabled, elementTheme, spell],
  );
}

function QuickChannelButtonWrapper(props: { spell: Spell }) {
  const state = useGameState();
  const spell = props.spell;

  if (!spell.isVisible(state)) {
    return null;
  }

  return <QuickChannelButton spell={props.spell} />;
}

export function QuickChannel(props: {}) {
  const spells = useMemo(
    () =>
      Spells.getAll().filter(
        (spell) =>
          spell.getAutocastCategory() == SpellAutocastCategory.CHANNELING,
      ),
    [],
  );

  return (
    <View style={[Styles.flexRowAlignCenter, { flexWrap: "wrap", gap: 2 }]}>
      {spells.map((spell) => (
        <QuickChannelButtonWrapper key={spell.getId()} spell={spell} />
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  buttonContentStyle: {
    marginHorizontal: 0,
    marginVertical: 0,
    height: 36,
    minWidth: 36,
  },
  buttonLabelStyle: {
    marginHorizontal: 0,
    marginVertical: 0,
  },
  buttonStyle: {
    height: 36,
    minWidth: 36,
    paddingHorizontal: 0,
  },
});
