import { t } from "../../../../utils/I18n";
import { GameState } from "../../../GameState";
import { registerPostRetirementListener } from "../../../Retire";
import GatherMana from "../../../action/actions/GatherMana";
import { ExplorationStatus } from "../../../exploration/ExplorationStatus";
import { getExplorationStatus } from "../../../exploration/ExplorationUtils";
import { getCurrentEnemy } from "../../../exploration/enemies/Enemies";
import {
  TransformationType,
  registerTransformation,
} from "../../../transformation/Transformation";
import { EquipmentSlot } from "../../Equipment";
import { addToInventory } from "../../Inventory";
import { ItemParams } from "../../Item";
import { EquippableItem } from "../EquippableItem";

class HeadmastersStaff extends EquippableItem {
  getId(): string {
    return "headmastersStaff";
  }
  getSlot(): EquipmentSlot {
    return EquipmentSlot.Hand;
  }
  getPicture() {
    return require("./headmastersStaff.png");
  }
  getBaseName(params: ItemParams): string {
    return t("Headmaster's Staff");
  }
  getDescription(state: GameState, params: ItemParams): string | undefined {
    return t("*You are not worthy.*");
  }
  getBaseSalePrice(state: GameState, params: ItemParams): number {
    return 1;
  }

  getAttackBonusBase(params: ItemParams): number {
    return 20;
  }

  getManaRegenBonusBase(params: ItemParams): number {
    return 15;
  }

  getEffectExtra(state: GameState, params: ItemParams): string {
    return t("If not fighting a Boss, 10x effectivity of Gather Mana");
  }
}

export const headmastersStaff = new HeadmastersStaff();

registerTransformation(
  [[GatherMana.getId(), "mana"]],
  headmastersStaff.getId(),
  headmastersStaff.getDefaultName(),
  TransformationType.Multiplier,
  (state) =>
    headmastersStaff.isEquippedWithAnyParams(state) &&
    (getExplorationStatus(state) != ExplorationStatus.Combat ||
      !getCurrentEnemy(state)?.isBoss?.())
      ? 10.0
      : 1.0,
);

registerPostRetirementListener(headmastersStaff.getId(), (state) => {
  if (state.global.mr1flags.creation && state.options.enableMr1Rewards) {
    state = addToInventory(
      { itemId: headmastersStaff.getId(), params: {} },
      1,
      state,
    );
  }
  return state;
});
